import { Box, Container, Stack, Typography, useMediaQuery, useTheme } from "@mui/material";
import masterData from "../../data/masterData.json";
import { getIcon } from "../../utils/iconMap";
import LeadFormCard from "./LeadFormCard";
import type { Specialty } from "../../types/fellowship";

interface HeroSectionProps {
  specialty?: Specialty | null;
}

export default function HeroSection({ specialty = null }: HeroSectionProps) {
  const { brand, hero } = masterData;
  const theme = useTheme();
  const isMdUp = useMediaQuery(theme.breakpoints.up("md"));
  const isLgUp = useMediaQuery(theme.breakpoints.up("lg"));

  const headlineBefore = specialty?.headlineBefore || hero.headlineBefore;
  const headlineHighlight = specialty?.headlineHighlight || hero.headlineHighlight;
  const subheadline = specialty?.subheadline || hero.subheadline;
  const description = specialty?.heroDescription || hero.description;
  const doctorImage = specialty?.heroImage || hero.image;

  return (
    <Box
      sx={{
        position: "relative",
        overflow: "hidden",
        minHeight: { xs: "auto", md: 620, lg: 680, xl: 720, tv: 780 },
        pb: { xs: 4, md: 0 },
      }}
    >
      <Box
        sx={{
          position: "absolute",
          inset: 0,
          backgroundImage: `linear-gradient(90deg, rgba(243,247,255,0.97) 0%, rgba(238,244,252,0.88) 42%, rgba(232,242,255,0.55) 65%, rgba(255,255,255,0.35) 100%), url(${hero.background})`,
          backgroundSize: "cover",
          backgroundPosition: "center",
          filter: "saturate(0.85)",
        }}
      />
      <Box
        sx={{
          position: "absolute",
          inset: 0,
          opacity: 0.28,
          backgroundImage: "radial-gradient(circle, rgba(0,86,210,0.22) 1px, transparent 1px)",
          backgroundSize: "24px 24px",
          pointerEvents: "none",
        }}
      />

      <Container
        maxWidth="lg"
        sx={{ position: "relative", zIndex: 2, pt: { xs: 2, md: 2.5, tv: 3.5 }, pb: { xs: 2, md: 4, tv: 5 } }}
      >
        <Stack direction="row" alignItems="center" spacing={1.1} sx={{ mb: { xs: 2.5, md: 3 } }}>
          <Box
            component="img"
            src={brand.logo}
            alt={brand.name}
            sx={{ width: { xs: 30, md: 36 }, height: { xs: 30, md: 36 } }}
          />
          <Typography sx={{ fontWeight: 800, fontSize: { xs: 13, md: 14, tv: 16 }, letterSpacing: "0.08em", color: "#0B1F3A" }}>
            {brand.name}
          </Typography>
        </Stack>

        <Box
          sx={{
            position: "relative",
            display: "grid",
            gridTemplateColumns: {
              xs: "1fr",
              md: "minmax(0, 1fr) minmax(300px, 380px)",
              lg: "minmax(0, 1.05fr) minmax(340px, 400px)",
              tv: "minmax(0, 1.1fr) minmax(380px, 440px)",
            },
            columnGap: { md: 3, lg: 5, tv: 8 },
            rowGap: { xs: 3, md: 0 },
            alignItems: "start",
            minHeight: { md: 540, lg: 580, tv: 640 },
          }}
        >
          {isMdUp && (
            <Box
              key={doctorImage}
              sx={{
                position: "absolute",
                left: { md: "38%", lg: "42%", xl: "44%", tv: "46%" },
                bottom: 0,
                transform: "translateX(-50%)",
                width: { md: 340, lg: 420, xl: 460, tv: 520 },
                height: { md: 520, lg: 600, xl: 640, tv: 700 },
                zIndex: 1,
                pointerEvents: "none",
              }}
            >
              <Box
                sx={{
                  position: "absolute",
                  bottom: 30,
                  left: "50%",
                  transform: "translateX(-50%)",
                  width: "90%",
                  height: "55%",
                  borderRadius: "50%",
                  background: "radial-gradient(circle, rgba(160,198,255,0.7) 0%, transparent 70%)",
                  filter: "blur(12px)",
                }}
              />
              <Box
                component="img"
                src={doctorImage}
                alt={specialty?.name || "Fellowship doctor"}
                sx={{
                  position: "relative",
                  zIndex: 1,
                  width: "100%",
                  height: "100%",
                  objectFit: "contain",
                  objectPosition: "bottom center",
                  filter: "drop-shadow(0 12px 28px rgba(0,40,100,0.18))",
                }}
              />
            </Box>
          )}

          <Box
            sx={{
              position: "relative",
              zIndex: 3,
              maxWidth: { md: 440, lg: 480, tv: 560 },
              pt: { md: 0.5 },
              order: { xs: 1, md: 0 },
            }}
          >
            <Typography
              sx={{
                color: "#0056D2",
                fontWeight: 700,
                fontSize: { xs: 10, md: 11, tv: 12 },
                letterSpacing: "0.14em",
                mb: 1.5,
              }}
            >
              {specialty ? specialty.name.toUpperCase() : brand.eyebrow}
            </Typography>

            <Typography
              component="h1"
              sx={{
                fontWeight: 800,
                color: "#0B1F3A",
                fontSize: { xs: "1.65rem", sm: "1.95rem", md: "2.2rem", lg: "2.45rem", tv: "2.9rem" },
                lineHeight: 1.15,
                mb: 1.5,
                letterSpacing: "-0.025em",
              }}
            >
              {headlineBefore}
              <Box component="span" sx={{ color: "#0056D2", display: { xs: "inline", sm: "block" } }}>
                {headlineHighlight}
              </Box>
            </Typography>

            <Typography sx={{ fontWeight: 700, color: "#0B1F3A", fontSize: { xs: 15, md: 16.5, tv: 19 }, mb: 1.25 }}>
              {subheadline}
            </Typography>

            <Box sx={{ position: "relative", mb: 2.5, maxWidth: 400 }}>
              <Typography sx={{ color: "#5A6B80", fontSize: { xs: 13.5, md: 14.5, tv: 16 }, lineHeight: 1.7 }}>
                {description}
              </Typography>
              {isLgUp && (
                <Typography
                  sx={{
                    position: "absolute",
                    right: { lg: -90, xl: -70, tv: -40 },
                    top: { lg: 40, tv: 20 },
                    width: 120,
                    fontFamily: "'Dancing Script', cursive",
                    fontSize: { lg: 18, tv: 22 },
                    lineHeight: 1.2,
                    color: "#0056D2",
                    fontWeight: 700,
                    textAlign: "center",
                    transform: "rotate(-8deg)",
                    whiteSpace: "pre-line",
                    textShadow: "0 1px 0 rgba(255,255,255,0.8)",
                  }}
                >
                  {hero.scriptText}
                </Typography>
              )}
            </Box>

            <Box
              sx={{
                display: "grid",
                gridTemplateColumns: "1fr 1fr",
                gap: { xs: 1.25, md: 1.5 },
                mb: 2.25,
                maxWidth: 440,
              }}
            >
              {hero.stats.map((stat) => {
                const Icon = getIcon(stat.icon);
                return (
                  <Stack key={stat.id} direction="row" spacing={1} alignItems="center">
                    <Box
                      sx={{
                        width: { xs: 32, tv: 38 },
                        height: { xs: 32, tv: 38 },
                        borderRadius: "50%",
                        bgcolor: "rgba(229,240,255,0.95)",
                        display: "flex",
                        alignItems: "center",
                        justifyContent: "center",
                        flexShrink: 0,
                        border: "1px solid #D6E6FF",
                      }}
                    >
                      <Icon sx={{ color: "#0056D2", fontSize: { xs: 17, tv: 20 } }} />
                    </Box>
                    <Typography sx={{ fontSize: { xs: 12, md: 12.5, tv: 14 }, fontWeight: 700, color: "#0B1F3A", lineHeight: 1.25 }}>
                      {stat.value ? (
                        <>
                          <Box component="span" sx={{ color: "#0056D2" }}>
                            {stat.value}
                          </Box>{" "}
                          {stat.label}
                        </>
                      ) : (
                        stat.label
                      )}
                    </Typography>
                  </Stack>
                );
              })}
            </Box>

            <Stack
              direction="row"
              alignItems="center"
              spacing={1.25}
              sx={{
                display: "inline-flex",
                bgcolor: "rgba(255,255,255,0.95)",
                border: "1px solid #E0EAF6",
                borderRadius: "14px",
                px: 1.5,
                py: 1,
                boxShadow: "0 6px 20px rgba(0,86,210,0.1)",
              }}
            >
              <Box component="img" src={hero.cpdBadge} alt="CPD" sx={{ width: 40, height: 40 }} />
              <Box>
                <Typography sx={{ fontSize: { xs: 12, tv: 13 }, fontWeight: 700, color: "#0B1F3A" }}>
                  {hero.cpdLabel}
                </Typography>
                {hero.cpdSubLabel && (
                  <Typography sx={{ fontSize: 10, color: "#6B7C93" }}>{hero.cpdSubLabel}</Typography>
                )}
              </Box>
            </Stack>
          </Box>

          <Box
            sx={{
              position: "relative",
              zIndex: 4,
              justifySelf: { xs: "stretch", md: "end" },
              width: "100%",
              maxWidth: { xs: "100%", md: 400, tv: 440 },
              order: { xs: 3, md: 0 },
            }}
          >
            <LeadFormCard key={specialty?.id || "default"} defaultSpecialty={specialty?.id || ""} />
          </Box>

          {!isMdUp && (
            <Box sx={{ gridColumn: "1 / -1", display: "flex", justifyContent: "center", order: 2, my: 0.5 }}>
              <Box
                component="img"
                key={doctorImage}
                src={doctorImage}
                alt={specialty?.name || "Fellowship doctor"}
                sx={{
                  width: "min(78%, 320px)",
                  height: { xs: 340, sm: 400 },
                  objectFit: "contain",
                  objectPosition: "bottom",
                  filter: "drop-shadow(0 10px 24px rgba(0,40,100,0.15))",
                }}
              />
            </Box>
          )}
        </Box>
      </Container>
    </Box>
  );
}
